#define DT_DRV_COMPAT zephyr_bbram_emul

#include <string.h>

#include <zephyr/device.h>
#include <zephyr/drivers/bbram.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(bbram_emul, CONFIG_BBRAM_LOG_LEVEL);

static uint8_t emul_bbram_buf[CONFIG_BBRAM_EMUL_SIZE];

struct bbram_emul_config {
	size_t size;
};

static int bbram_emul_read(const struct device *dev, size_t offset, size_t size,
			   uint8_t *data)
{
	const struct bbram_emul_config *config = dev->config;

	if ((offset + size) > config->size || (offset + size) < offset) {
		return -EFAULT;
	}

	memcpy(data, &emul_bbram_buf[offset], size);

	return 0;
}

static int bbram_emul_write(const struct device *dev, size_t offset, size_t size,
			    const uint8_t *data)
{
	const struct bbram_emul_config *config = dev->config;

	if ((offset + size) > config->size || (offset + size) < offset) {
		return -EFAULT;
	}

	memcpy(&emul_bbram_buf[offset], data, size);

	return 0;
}

static int bbram_emul_get_size(const struct device *dev, size_t *size)
{
	const struct bbram_emul_config *config = dev->config;

	*size = config->size;

	return 0;
}

static const struct bbram_driver_api bbram_emul_api = {
	.read = bbram_emul_read,
	.write = bbram_emul_write,
	.get_size = bbram_emul_get_size,
};

static int bbram_emul_init(const struct device *dev)
{
	const struct bbram_emul_config *config = dev->config;

	if (config->size > ARRAY_SIZE(emul_bbram_buf)) {
		LOG_ERR("emulated bbram size is too large");
		return -EINVAL;
	}

	return 0;
}

#define BBRAM_EMUL_INIT(n)                                                                         \
	static const struct bbram_emul_config bbram_emul_config_##n = {                             \
		.size = DT_INST_PROP(n, size),                                                     \
	};                                                                                         \
	                                                                                           \
	DEVICE_DT_INST_DEFINE(n, bbram_emul_init, NULL, NULL, &bbram_emul_config_##n,               \
			      POST_KERNEL, CONFIG_BBRAM_INIT_PRIORITY, &bbram_emul_api);

DT_INST_FOREACH_STATUS_OKAY(BBRAM_EMUL_INIT)
